	private static ArtifactDescriptor describe(Path artifact) throws IOException {
		if (Files.isSymbolicLink(artifact)) {
			throw new IOException("LMDB bulk-load artifacts must not be symbolic links: " + artifact);
		}
		if (Files.isRegularFile(artifact)) {
			return new ArtifactDescriptor(artifact.getFileName().toString(), "file", Files.size(artifact),
					digestFile(artifact));
		}
		if (!Files.isDirectory(artifact)) {
			throw new IOException("Unsupported LMDB bulk-load artifact: " + artifact);
		}
		MessageDigest digest = sha256();
		long size = 0L;
		List<Path> paths;
		try (var walk = Files.walk(artifact)) {
			paths = walk.sorted(Comparator.comparing(path -> artifact.relativize(path).toString())).toList();
		}
		for (Path path : paths) {
			if (Files.isSymbolicLink(path)) {
				throw new IOException("LMDB bulk-load artifacts must not contain symbolic links: " + path);
			}
			String relative = artifact.relativize(path).toString().replace(path.getFileSystem().getSeparator(), "/");
			updateString(digest, relative);
			if (Files.isDirectory(path)) {
				digest.update((byte) 0);
			} else if (Files.isRegularFile(path)) {
				digest.update((byte) 1);
				long fileSize = Files.size(path);
				updateLong(digest, fileSize);
				size = Math.addExact(size, fileSize);
				updateFile(digest, path);
			} else {
				throw new IOException("Unsupported file in LMDB bulk-load artifact: " + path);
			}
		}
		return new ArtifactDescriptor(artifact.getFileName().toString(), "directory", size,
				HexFormat.of().formatHex(digest.digest()));
	}

