	private static String digestFile(Path file) throws IOException {
		MessageDigest digest = sha256();
		updateFile(digest, file);
		return HexFormat.of().formatHex(digest.digest());
	}

	private static void updateFile(MessageDigest digest, Path file) throws IOException {
		byte[] buffer = new byte[DIGEST_BUFFER_BYTES];
		try (InputStream input = Files.newInputStream(file)) {
			int read;
			while ((read = input.read(buffer)) >= 0) {
				if (read > 0) {
					digest.update(buffer, 0, read);
				}
			}
		}
	}

	private static void updateString(MessageDigest digest, String value) {
		byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
		updateLong(digest, bytes.length);
		digest.update(bytes);
	}

	private static void updateLong(MessageDigest digest, long value) {
		digest.update(ByteBuffer.allocate(Long.BYTES).putLong(value).array());
	}

	private static MessageDigest sha256() {
		try {
			return MessageDigest.getInstance("SHA-256");
		} catch (NoSuchAlgorithmException e) {
			throw new AssertionError("The Java runtime must provide SHA-256", e);
		}
	}

